-- Local Creation integration only.  The verified R24 Creation state machine
-- remains JPA based, so these PostgreSQL tables deliberately match its actual
-- V2--V4 mapping while catalog_users/catalog_paintings remain the canonical
-- identities.  This is a same-database compatibility projection, never a
-- SQLite mirror or a production cutover migration.

CREATE VIEW users AS
SELECT id, username, password_hash AS password, full_name, email, enabled,
       account_non_expired, account_non_locked, credentials_non_expired, role,
       created_at, updated_at
FROM catalog_users;

CREATE TABLE media_assets (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id VARCHAR(64) NOT NULL UNIQUE,
    owner_user_id BIGINT REFERENCES catalog_users(id) ON DELETE RESTRICT,
    storage_key VARCHAR(1024) NOT NULL UNIQUE,
    original_filename VARCHAR(512) NOT NULL,
    mime_type VARCHAR(255), file_size BIGINT, sha256 VARCHAR(64),
    width INTEGER, height INTEGER, duration_seconds DOUBLE PRECISION,
    asset_type VARCHAR(64) NOT NULL, semantic_type VARCHAR(64) NOT NULL,
    source_type VARCHAR(64) NOT NULL, visibility VARCHAR(64) NOT NULL,
    status VARCHAR(64) NOT NULL, created_at TIMESTAMP NOT NULL,
    updated_at TIMESTAMP NOT NULL
);
CREATE INDEX idx_media_assets_owner_created ON media_assets(owner_user_id, created_at);
CREATE INDEX idx_media_assets_type_status ON media_assets(asset_type, semantic_type, status);
CREATE INDEX idx_media_assets_sha256 ON media_assets(sha256);

CREATE TABLE paintings (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id VARCHAR(64) NOT NULL UNIQUE, source_key VARCHAR(1024) NOT NULL UNIQUE,
    source_sequence VARCHAR(64), image_storage_name VARCHAR(512) NOT NULL,
    title VARCHAR(512), author_name VARCHAR(255), author_birth_year VARCHAR(64),
    author_birth_place VARCHAR(512), author_school VARCHAR(255), creation_year VARCHAR(255),
    creation_dynasty_raw VARCHAR(255), creation_dynasty_normalized VARCHAR(255),
    actual_size VARCHAR(255), collection_institution VARCHAR(512), category VARCHAR(255),
    subject VARCHAR(512), painting_school VARCHAR(255), style TEXT, color TEXT,
    composition TEXT, artistic_conception TEXT, brushwork TEXT, ink_method TEXT,
    painting_material TEXT, pigment TEXT, seal TEXT, cultural_symbol TEXT,
    generated_text TEXT, music_scene_description TEXT, collection_platform VARCHAR(512),
    image_asset_id BIGINT REFERENCES media_assets(id) ON DELETE SET NULL,
    image_available BOOLEAN NOT NULL DEFAULT FALSE, visible_in_gallery BOOLEAN NOT NULL DEFAULT TRUE,
    status VARCHAR(64) NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL
);
CREATE INDEX idx_paintings_image_storage_name ON paintings(image_storage_name);
CREATE INDEX idx_paintings_gallery_status ON paintings(visible_in_gallery, status);
CREATE INDEX idx_paintings_dynasty ON paintings(creation_dynasty_normalized);
CREATE INDEX idx_paintings_category ON paintings(category);
CREATE INDEX idx_paintings_author_name ON paintings(author_name);
CREATE INDEX idx_paintings_image_asset ON paintings(image_asset_id);

-- This one-to-one ledger makes the numerical JPA compatibility IDs auditable.
-- It is populated only by the explicit local projection command.
CREATE TABLE catalog_creation_painting_projection (
    catalog_painting_id UUID PRIMARY KEY REFERENCES catalog_paintings(public_id) ON DELETE RESTRICT,
    jpa_painting_id BIGINT NOT NULL UNIQUE REFERENCES paintings(id) ON DELETE RESTRICT,
    catalog_asset_id UUID REFERENCES catalog_media_assets(public_id) ON DELETE RESTRICT,
    jpa_asset_id BIGINT UNIQUE REFERENCES media_assets(id) ON DELETE RESTRICT,
    input_batch_id UUID NOT NULL, input_revision INTEGER NOT NULL,
    projected_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    FOREIGN KEY (input_batch_id, input_revision)
      REFERENCES catalog_batch_revisions(batch_id, revision) ON DELETE RESTRICT
);

CREATE TABLE user_workflows (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id VARCHAR(64) NOT NULL UNIQUE, user_id BIGINT NOT NULL REFERENCES catalog_users(id) ON DELETE RESTRICT,
    name VARCHAR(255) NOT NULL, description TEXT, graph_json TEXT NOT NULL,
    schema_version INTEGER NOT NULL, status VARCHAR(64) NOT NULL,
    created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL
);
CREATE INDEX idx_user_workflows_user_status_updated ON user_workflows(user_id, status, updated_at);

CREATE TABLE creations (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id VARCHAR(64) NOT NULL UNIQUE, user_id BIGINT NOT NULL REFERENCES catalog_users(id) ON DELETE RESTRICT,
    workflow_id BIGINT REFERENCES user_workflows(id) ON DELETE SET NULL,
    workflow_snapshot TEXT NOT NULL, source_modality VARCHAR(64) NOT NULL, source_text TEXT,
    source_painting_id BIGINT REFERENCES paintings(id) ON DELETE RESTRICT,
    source_asset_id BIGINT REFERENCES media_assets(id) ON DELETE RESTRICT,
    status VARCHAR(64) NOT NULL, final_modality VARCHAR(64),
    final_asset_id BIGINT REFERENCES media_assets(id) ON DELETE RESTRICT,
    final_output_json TEXT, created_at TIMESTAMP NOT NULL, started_at TIMESTAMP,
    finished_at TIMESTAMP, error_code VARCHAR(128), error_message TEXT,
    updated_at TIMESTAMP NOT NULL, claim_token VARCHAR(64), lease_expires_at TIMESTAMP,
    retry_version INTEGER NOT NULL DEFAULT 0 CHECK (retry_version >= 0),
    legacy_original_status VARCHAR(64)
);
CREATE INDEX idx_creations_user_created ON creations(user_id, created_at);
CREATE INDEX idx_creations_user_status ON creations(user_id, status);
CREATE INDEX idx_creations_workflow ON creations(workflow_id);
CREATE INDEX idx_creations_source_painting ON creations(source_painting_id);
CREATE INDEX idx_creations_source_asset ON creations(source_asset_id);
CREATE INDEX idx_creations_final_asset ON creations(final_asset_id);
CREATE INDEX idx_creations_status_created_id ON creations(status, created_at, id);
CREATE INDEX idx_creations_status_lease_id ON creations(status, lease_expires_at, id);
CREATE INDEX idx_creations_user_created_public ON creations(user_id, created_at, public_id);

CREATE TABLE creation_steps (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id VARCHAR(64) NOT NULL UNIQUE, creation_id BIGINT NOT NULL REFERENCES creations(id) ON DELETE CASCADE,
    step_index INTEGER NOT NULL, node_id VARCHAR(255) NOT NULL, operation_code VARCHAR(128) NOT NULL,
    provider_code VARCHAR(128), input_modality VARCHAR(64) NOT NULL, output_modality VARCHAR(64) NOT NULL,
    input_json TEXT, parameters_json TEXT, output_json TEXT,
    input_asset_id BIGINT REFERENCES media_assets(id) ON DELETE RESTRICT,
    output_asset_id BIGINT REFERENCES media_assets(id) ON DELETE RESTRICT,
    status VARCHAR(64) NOT NULL, attempt_count INTEGER NOT NULL DEFAULT 0,
    error_code VARCHAR(128), error_message TEXT, started_at TIMESTAMP, finished_at TIMESTAMP,
    provider_dispatch_state VARCHAR(32) NOT NULL DEFAULT 'NOT_SENT', provider_request_key VARCHAR(128),
    CONSTRAINT uq_creation_steps_creation_index UNIQUE(creation_id, step_index)
);
CREATE INDEX idx_creation_steps_creation_status ON creation_steps(creation_id, status);
CREATE INDEX idx_creation_steps_input_asset ON creation_steps(input_asset_id);
CREATE INDEX idx_creation_steps_output_asset ON creation_steps(output_asset_id);

CREATE TABLE creation_execution_attempts (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    creation_id BIGINT NOT NULL REFERENCES creations(id) ON DELETE CASCADE,
    attempt_number INTEGER NOT NULL CHECK (attempt_number >= 1),
    retry_idempotency_key_digest VARCHAR(64), admitted_at TIMESTAMP NOT NULL,
    finished_at TIMESTAMP, resolution_code VARCHAR(128),
    CONSTRAINT uq_creation_execution_attempts_creation_number UNIQUE(creation_id, attempt_number),
    CONSTRAINT uq_creation_execution_attempts_creation_idempotency UNIQUE(creation_id, retry_idempotency_key_digest)
);
CREATE UNIQUE INDEX uq_creation_execution_attempts_one_active
  ON creation_execution_attempts(creation_id) WHERE finished_at IS NULL;
CREATE INDEX idx_creation_execution_attempts_creation_admitted
  ON creation_execution_attempts(creation_id, admitted_at, id);

CREATE TABLE creation_step_dispatch_attempts (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    creation_step_id BIGINT NOT NULL REFERENCES creation_steps(id) ON DELETE CASCADE,
    creation_execution_attempt_id BIGINT NOT NULL REFERENCES creation_execution_attempts(id) ON DELETE CASCADE,
    provider_request_key VARCHAR(128) UNIQUE, dispatch_state VARCHAR(32) NOT NULL DEFAULT 'NOT_SENT',
    dispatch_started_at TIMESTAMP, finished_at TIMESTAMP, resolution_code VARCHAR(128),
    result_asset_id BIGINT REFERENCES media_assets(id) ON DELETE RESTRICT,
    result_digest VARCHAR(64), canonical_poem_digest VARCHAR(64),
    CONSTRAINT uq_creation_step_dispatch_attempts_step_execution
      UNIQUE(creation_step_id, creation_execution_attempt_id)
);
CREATE INDEX idx_creation_step_dispatch_attempts_step ON creation_step_dispatch_attempts(creation_step_id, id);
CREATE INDEX idx_creation_step_dispatch_attempts_execution ON creation_step_dispatch_attempts(creation_execution_attempt_id, id);

-- The entity/repository exists but no R24 API consumes Creation favourites.
-- Preserve this dormant legacy concept; it is not enabled as a new feature here.
CREATE TABLE creation_favorites (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    public_id VARCHAR(64) NOT NULL UNIQUE, user_id BIGINT NOT NULL REFERENCES catalog_users(id) ON DELETE CASCADE,
    creation_id BIGINT NOT NULL REFERENCES creations(id) ON DELETE CASCADE, created_at TIMESTAMP NOT NULL,
    CONSTRAINT uq_creation_favorites_user_creation UNIQUE(user_id, creation_id)
);
CREATE INDEX idx_creation_favorites_user_created ON creation_favorites(user_id, created_at);
CREATE INDEX idx_creation_favorites_user_created_public ON creation_favorites(user_id, created_at, public_id);
CREATE INDEX idx_creation_favorites_creation_user ON creation_favorites(creation_id, user_id);

-- generation_logs is consumed by /api/user/logs and GenerationService audit UI;
-- it is not consulted by Creation queue/recovery state transitions.
CREATE TABLE generation_logs (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id BIGINT NOT NULL REFERENCES catalog_users(id) ON DELETE RESTRICT,
    task_type VARCHAR(255) NOT NULL, api_source VARCHAR(255) NOT NULL, api_provider VARCHAR(255),
    input_data TEXT, output_data TEXT, image_url VARCHAR(1024), result_url VARCHAR(1024),
    description VARCHAR(1024), model_size VARCHAR(255) NOT NULL, use_fast_generate BOOLEAN NOT NULL,
    duration INTEGER, processing_time_ms BIGINT, success BOOLEAN NOT NULL,
    error_message VARCHAR(1024), metadata TEXT, created_at TIMESTAMP NOT NULL
);
CREATE INDEX idx_generation_logs_user_created ON generation_logs(user_id, created_at DESC, id DESC);

CREATE TABLE catalog_legacy_creation_imports (
    source_id TEXT PRIMARY KEY, source_sha256 CHAR(64) NOT NULL CHECK(source_sha256 ~ '^[0-9a-f]{64}$'),
    mapping_sha256 CHAR(64) NOT NULL CHECK(mapping_sha256 ~ '^[0-9a-f]{64}$'),
    status TEXT NOT NULL CHECK(status = 'SUCCEEDED'), imported_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    imported_workflows INTEGER NOT NULL, imported_creations INTEGER NOT NULL,
    imported_assets INTEGER NOT NULL, imported_logs INTEGER NOT NULL, imported_held INTEGER NOT NULL
);
CREATE TABLE catalog_legacy_creation_import_attempts (
    attempt_id UUID PRIMARY KEY, source_id TEXT NOT NULL,
    input_fingerprint CHAR(64) NOT NULL CHECK(input_fingerprint ~ '^[0-9a-f]{64}$'),
    outcome TEXT NOT NULL CHECK(outcome IN ('STARTED','SUCCEEDED','NOOP_REIMPORT','FAILED','CONFLICT')),
    failure_code TEXT, failure_message TEXT, started_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    finished_at TIMESTAMPTZ
);
CREATE INDEX idx_catalog_legacy_creation_import_attempts_source
  ON catalog_legacy_creation_import_attempts(source_id, started_at DESC);
